def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors=set(v for row in grid for v in row if v!=bg)
    out=[[bg]*w for _ in range(h)]
    for color in colors:
        # 2D prefix sum, allowing an efficient search for dense rectangles.
        ps=[[0]*(w+1) for _ in range(h+1)]
        for r in range(h):
            s=0
            for c in range(w):
                s += grid[r][c]==color
                ps[r+1][c+1]=ps[r][c+1]+s
        def count(r0,r1,c0,c1):
            return ps[r1+1][c1+1]-ps[r0][c1+1]-ps[r1+1][c0]+ps[r0][c0]
        for r0 in range(h):
            for r1 in range(r0+1,h):
                for c0 in range(w):
                    for c1 in range(c0+1,w):
                        area=(r1-r0+1)*(c1-c0+1)
                        if area<4: continue
                        n=count(r0,r1,c0,c1)
                        if n/area < .78: continue
                        row_min=min(count(r,r,c0,c1)/(c1-c0+1) for r in range(r0,r1+1))
                        col_min=min(count(r0,r1,c,c)/(r1-r0+1) for c in range(c0,c1+1))
                        if row_min < .60 or col_min < .60: continue
                        for r in range(r0,r1+1):
                            for c in range(c0,c1+1): out[r][c]=color
    return out

